PRAGMA journal_mode = WAL;

CREATE TABLE IF NOT EXISTS stores (id TEXT PRIMARY KEY, owner TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'DRAFT', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS brands (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, title TEXT NOT NULL, shopify_product_id TEXT, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS variants (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, product_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS suppliers (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, name TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS supplier_products (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, supplier_id TEXT NOT NULL, external_ref TEXT NOT NULL, product_cost REAL NOT NULL, shipping_cost REAL NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS markets (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS catalogs (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS prices (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, product_id TEXT NOT NULL, amount REAL NOT NULL, currency TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS cost_history (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, product_id TEXT NOT NULL, total_cost REAL NOT NULL, currency TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS inventory_state (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, product_id TEXT NOT NULL, quantity INTEGER, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS fulfillments (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, order_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS support_cases (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS experiments (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS metrics (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, metric_name TEXT NOT NULL, metric_value REAL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, severity TEXT NOT NULL, summary TEXT NOT NULL, owner TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, evidence TEXT NOT NULL DEFAULT '[]', verification_state TEXT NOT NULL DEFAULT 'UNKNOWN');
CREATE TABLE IF NOT EXISTS work_orders (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, objective TEXT NOT NULL, resource TEXT NOT NULL, current_state TEXT NOT NULL, desired_state TEXT NOT NULL, primary_owner TEXT NOT NULL, expected_value REAL NOT NULL DEFAULT 0, risk TEXT NOT NULL DEFAULT 'LOW', cost REAL NOT NULL DEFAULT 0, dependencies TEXT NOT NULL DEFAULT '[]', acceptance_criteria TEXT NOT NULL, rollback_plan TEXT NOT NULL, verification_method TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS resource_leases (store_id TEXT NOT NULL, resource TEXT NOT NULL, owner TEXT NOT NULL, lease_expires_at TEXT NOT NULL, PRIMARY KEY (store_id, resource));
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, agent_name TEXT NOT NULL, work_order_id TEXT, status TEXT NOT NULL, telemetry TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, work_order_id TEXT NOT NULL, approval_type TEXT NOT NULL, status TEXT NOT NULL, requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, decided_at TEXT, decided_by TEXT, evidence TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, source_type TEXT NOT NULL, source_ref TEXT NOT NULL, claim TEXT NOT NULL, verification_state TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS execution_ledger (id TEXT PRIMARY KEY, store_id TEXT NOT NULL, work_order_id TEXT, action TEXT NOT NULL, before_state TEXT NOT NULL DEFAULT '{}', diff TEXT NOT NULL DEFAULT '{}', after_state TEXT NOT NULL DEFAULT '{}', verification_state TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
